-- The publish fields and listing versions (T280), generated by Prisma from schema.prisma, plus the
-- rules Prisma cannot express, hand-written at the end: one active package per address (a partial
-- unique index that a withdrawn package does not count against), a closing window that starts no
-- later than it ends, and listing versions that are append-only.

-- DropIndex
DROP INDEX "ListingPackage_addressHash_key";

-- AlterTable
ALTER TABLE "ListingPackage" ADD COLUMN     "closingWindowEnd" DATE,
ADD COLUMN     "closingWindowStart" DATE,
ADD COLUMN     "currentlyListed" BOOLEAN,
ADD COLUMN     "eligiblePrograms" "OfferProgram"[],
ADD COLUMN     "listingVersion" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "offerDeadline" TIMESTAMP(3),
ADD COLUMN     "publishedAt" TIMESTAMP(3),
ADD COLUMN     "round" INTEGER NOT NULL DEFAULT 1;

-- CreateTable
CREATE TABLE "ListingVersion" (
    "id" TEXT NOT NULL,
    "packageId" TEXT NOT NULL,
    "listingVersion" INTEGER NOT NULL,
    "round" INTEGER NOT NULL,
    "snapshot" JSONB NOT NULL,
    "evaluatorVersion" INTEGER NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "ListingVersion_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "ListingVersion_packageId_listingVersion_key" ON "ListingVersion"("packageId", "listingVersion");

-- CreateIndex
CREATE INDEX "ListingPackage_addressHash_idx" ON "ListingPackage"("addressHash");

-- AddForeignKey
ALTER TABLE "ListingVersion" ADD CONSTRAINT "ListingVersion_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "ListingPackage"("id") ON DELETE RESTRICT ON UPDATE CASCADE;



-- CreateIndex (hand-written): one active package per address (FR-013). A withdrawn package frees
-- the address; CLOSED joins the exclusion when packages can close.
CREATE UNIQUE INDEX "ListingPackage_one_active_per_address" ON "ListingPackage"("addressHash")
    WHERE status <> 'WITHDRAWN';

-- AddCheck (hand-written): the seller's closing window starts no later than it ends.
ALTER TABLE "ListingPackage" ADD CONSTRAINT "ListingPackage_closingWindow_check"
    CHECK ("closingWindowStart" <= "closingWindowEnd");

-- CreateTrigger (hand-written): listing versions are history, so they can be added but never
-- changed or removed.
CREATE FUNCTION "refuse_append_only_change"() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "ListingVersion_append_only" BEFORE UPDATE OR DELETE ON "ListingVersion"
    FOR EACH ROW EXECUTE FUNCTION "refuse_append_only_change"();
